<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Complete payment | Lokal Culture</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/commerce.css"></head>
<body><main class="empty-commerce confirmation"><p class="eyebrow">Secure checkout</p><h1>Your order is ready.</h1><p>Complete payment securely through Razorpay to confirm order <strong><?= htmlspecialchars($order['number']) ?></strong>.</p><button class="button" id="pay-button" type="button">Pay ₹<?= number_format($order['amount'], 0) ?> <span>→</span></button><form id="payment-verification" method="post" action="/payment/verify"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><input type="hidden" name="order_number" value="<?= htmlspecialchars($order['number']) ?>"><input type="hidden" name="razorpay_payment_id"><input type="hidden" name="razorpay_order_id"><input type="hidden" name="razorpay_signature"></form></main><script src="https://checkout.razorpay.com/v1/checkout.js"></script><script>document.getElementById('pay-button').addEventListener('click', function () { const checkout = new Razorpay({ key: <?= json_encode($publicKey) ?>, amount: <?= (int) $gatewayOrder['amount'] ?>, currency: <?= json_encode($gatewayOrder['currency']) ?>, name: 'Lokal Culture', description: 'Order <?= htmlspecialchars($order['number'], ENT_QUOTES) ?>', order_id: <?= json_encode($gatewayOrder['id']) ?>, handler: function (response) { const form = document.getElementById('payment-verification'); form.querySelector('[name="razorpay_payment_id"]').value = response.razorpay_payment_id; form.querySelector('[name="razorpay_order_id"]').value = response.razorpay_order_id; form.querySelector('[name="razorpay_signature"]').value = response.razorpay_signature; form.submit(); } }); checkout.open(); });</script></body></html>